import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 목록 기본 크기 20, 최대 200
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

@Controller('api/v1')
export class FnSfr00108Controller {
  @Post('/card-transactions/receive')
  @HttpCode(200)
  async receiveCardTransactions(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자');
    const data = checks.inputOf(req.body);
    const idText = String(data['creditCardId'] ?? '');
    if (!/^\d+$/.test(idText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '신용카드를 선택해 주세요.');
    }
    const startDate = String(data['startDate'] ?? '');
    const endDate = String(data['endDate'] ?? '');
    if (!DATE_PATTERN.test(startDate) || !DATE_PATTERN.test(endDate)) {
      throw new ApiError(422, 'INVALID_DATE_RANGE', '조회 기간을 정확히 입력해 주세요.');
    }
    return transaction(async (db) => {
      const range = await db.query(
        'SELECT (CAST(:startDate AS date) > CAST(:endDate AS date)) AS "invalid"',
        { startDate, endDate },
      );
      if (range[0]['invalid']) {
        throw new ApiError(422, 'INVALID_DATE_RANGE', '시작일이 종료일보다 늦을 수 없습니다.');
      }
      const cards = await db.query(
        'SELECT credit_card_id AS "creditCardId" FROM credit_card WHERE credit_card_id = CAST(:id AS bigint)',
        { id: idText },
      );
      if (cards.length === 0) {
        throw new ApiError(404, 'CREDIT_CARD_NOT_FOUND', '등록되지 않은 신용카드입니다.');
      }
      // TODO: 카드사 연동 호출 방법과 수신 데이터 형식이 입력에 없어 저장할 내역이 없다.
      const errorReasons: string[] = [];
      return { receivedCount: 0, errorReasons };
    });
  }

  @Get('/card-transactions')
  async listCardTransactions(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자');
    const q = checks.queryOf(req.query);
    const pageNo = Math.max(0, Math.floor(Number(q['page'] ?? 0)) || 0);
    const sizeRaw = Math.floor(Number(q['size'] ?? DEFAULT_SIZE)) || DEFAULT_SIZE;
    const size = Math.min(MAX_SIZE, Math.max(1, sizeRaw));
    const idText = q['creditCardId'] === undefined || q['creditCardId'] === '' ? null : String(q['creditCardId']);
    if (idText !== null && !/^\d+$/.test(idText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '신용카드 값이 올바르지 않습니다.');
    }
    const startDate = q['startDate'] ? String(q['startDate']) : null;
    const endDate = q['endDate'] ? String(q['endDate']) : null;
    if ((startDate !== null && !DATE_PATTERN.test(startDate)) || (endDate !== null && !DATE_PATTERN.test(endDate))) {
      throw new ApiError(400, 'VALIDATION_FAILED', '날짜 형식이 올바르지 않습니다.');
    }
    const where =
      ' WHERE (CAST(:creditCardId AS bigint) IS NULL OR credit_card_id = CAST(:creditCardId AS bigint))' +
      ' AND (CAST(:startDate AS date) IS NULL OR approved_at >= CAST(:startDate AS date))' +
      ' AND (CAST(:endDate AS date) IS NULL OR approved_at < CAST(:endDate AS date) + 1)';
    return transaction(async (db) => {
      const filter = { creditCardId: idText, startDate, endDate };
      const items = await db.query(
        'SELECT card_transaction_id AS "cardTransactionId", credit_card_id AS "creditCardId",' +
          ' approval_no AS "approvalNo", approved_at AS "approvedAt", merchant_name AS "merchantName",' +
          ' total_amount AS "totalAmount", evidence_type AS "evidenceType"' +
          ' FROM card_transaction' +
          where +
          ' ORDER BY approved_at DESC, card_transaction_id DESC' +
          ' LIMIT :size OFFSET :offset',
        { ...filter, size, offset: pageNo * size },
      );
      const counted = await db.query('SELECT COUNT(*) AS "total" FROM card_transaction' + where, filter);
      return { items, page: pageNo, size, total: Number(counted[0]['total']) };
    });
  }
}

