import { useState } from 'react';
import {
  call,
  useData,
  Tiles,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Form,
  Field,
  DateInput,
  DateText,
  LookupSelect,
  RefName,
  Badge,
  Num,
  ErrorText,
  Pairs,
} from '../kit';
import type { PageProps, Page, Row } from '../kit';

export default function FnSfr00108Page({ role, notify }: PageProps) {
  const [cardId, setCardId] = useState<number | string>('');
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const [applied, setApplied] = useState<Row>({});
  const [pageNo, setPageNo] = useState(0);
  const [open, setOpen] = useState(false);
  const [recvCard, setRecvCard] = useState<number | string>('');
  const [recvFrom, setRecvFrom] = useState('');
  const [recvTo, setRecvTo] = useState('');
  const [result, setResult] = useState<Row | undefined>(undefined);

  const list = useData<Page>(
    () => call<Page>('GET', '/card-transactions', role, undefined, { ...applied, page: pageNo }),
    [applied, pageNo, role],
  );

  const search = () => {
    setPageNo(0);
    setApplied({ creditCardId: cardId, startDate: from, endDate: to });
  };

  const reset = () => {
    setCardId('');
    setFrom('');
    setTo('');
    setPageNo(0);
    setApplied({});
  };

  const receive = async () => {
    if (recvCard === '' || !recvFrom || !recvTo) {
      throw new Error('신용카드와 수신 기간을 모두 입력해 주세요.');
    }
    const res = await call('POST', '/card-transactions/receive', role, {
      creditCardId: recvCard,
      startDate: recvFrom,
      endDate: recvTo,
    });
    setResult(res);
    setOpen(false);
    notify('카드 사용 내역을 수신했습니다.');
    setPageNo(0);
    list.reload();
  };

  const reasons = Array.isArray(result?.['errorReasons']) ? (result?.['errorReasons'] as unknown[]) : [];

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>수신 현황</h2>
        <Tiles items={[['조회 건수', <Num value={list.data?.total ?? 0} />]]} />
        <Band>
          <button type="button" onClick={() => setOpen(true)}>내역 수신</button>
        </Band>
        {result && (
          <Pairs
            items={[
              ['수신 건수', <Num value={result['receivedCount']} />],
              ['오류·중복 사유', reasons.length === 0 ? '없음' : reasons.map(String).join(', ')],
            ]}
          />
        )}
      </section>
      <section className="box span-8">
        <h2>카드 사용 내역</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="신용카드 ID">
            <LookupSelect table="credit_card" role={role} value={cardId} onChange={setCardId} placeholder="전체" />
          </Field>
          <Field label="승인일 시작">
            <DateInput value={from} onChange={setFrom} />
          </Field>
          <Field label="승인일 종료">
            <DateInput value={to} onChange={setTo} />
          </Field>
        </Filters>
        {list.error && <ErrorText text={list.error} />}
        <DataTable
          rows={list.data?.items ?? []}
          empty="반영된 사용 내역이 없습니다."
          columns={[
            { key: 'creditCardId', label: '신용카드 ID', render: (r) => <RefName table="credit_card" role={role} value={r['creditCardId']} /> },
            { key: 'approvalNo', label: '승인번호' },
            { key: 'approvedAt', label: '승인일시', render: (r) => <DateText value={r['approvedAt']} time /> },
            { key: 'merchantName', label: '가맹점명' },
            { key: 'totalAmount', label: '합계금액', render: (r) => <Num value={r['totalAmount']} /> },
            { key: 'evidenceType', label: '증빙 유형', render: (r) => <Badge value={r['evidenceType']} /> },
          ]}
        />
        <Pager page={pageNo} size={list.data?.size ?? 20} total={list.data?.total ?? 0} onPage={setPageNo} />
      </section>
      {open && (
        <Drawer title="카드 사용 내역 수신" onClose={() => setOpen(false)}>
          <Form onSubmit={receive} submit="수신">
            <Field label="신용카드 ID" required>
              <LookupSelect table="credit_card" role={role} value={recvCard} onChange={setRecvCard} />
            </Field>
            <Field label="수신 시작일" required>
              <DateInput value={recvFrom} onChange={setRecvFrom} />
            </Field>
            <Field label="수신 종료일" required>
              <DateInput value={recvTo} onChange={setRecvTo} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
